UPDATE audio_cues SET config = json_set(config, '$.prompt', 'A half-full plastic water bucket is lowered onto the ground: muted plastic base thud, water surges against its inner wall and settles in two diminishing sloshes, then the handle taps the rim. Close natural location recording at arm length outdoors; believable weight, unprocessed texture and brief natural decay. Only the described action. No speech, music, cartoon effects, cinematic bass, electronic tones or added background machinery.', '$.duration', CASE WHEN json_extract(config, '$.duration') = 2 THEN 2.5 ELSE json_extract(config, '$.duration') END) WHERE game = 'first-person' AND cue = 'material.water.drop' AND json_extract(config, '$.prompt') = 'Realistic close-miked construction Foley outdoors. Physically accurate weight and texture. One isolated action with a clean transient and short natural decay. No music, voices, cartoon boing, synthetic beep, distortion or exaggerated reverb. Returning material to its supply station: a bucket of clean water, liquid sloshing and small splashes inside a hollow bucket.';
UPDATE audio_cues SET config = json_set(config, '$.prompt', 'A plastic bucket pours clean water into a stationary steel cement mixer drum: a short rim drip grows into a continuous hollow splashing stream, liquid gurgles at the bucket lip, splashes resonate softly inside steel, then a few separate final drops. Motor off; no powder hiss or gravel impacts. Close natural location recording at arm length outdoors; believable weight, unprocessed texture and brief natural decay. Only the described action. No speech, music, cartoon effects, cinematic bass, electronic tones or added background machinery.', '$.duration', CASE WHEN json_extract(config, '$.duration') = 2 THEN 3.5 ELSE json_extract(config, '$.duration') END) WHERE game = 'first-person' AND cue = 'material.water.pour' AND json_extract(config, '$.prompt') = 'Realistic close-miked construction Foley outdoors. Physically accurate weight and texture. One isolated action with a clean transient and short natural decay. No music, voices, cartoon boing, synthetic beep, distortion or exaggerated reverb. Pouring material into a stationary steel cement mixer drum: a bucket of clean water, liquid sloshing and small splashes inside a hollow bucket.';
UPDATE audio_cues SET config = json_set(config, '$.prompt', 'Thick fresh sand-and-cement mortar is transferred from a steel mixer mouth into a plastic bucket: slow heavy cohesive blobs fall with damp gritty plops, a short metal lip scrape, then sticky strands release. Dense paste, not freely splashing water; motor off. Close natural location recording at arm length outdoors; believable weight, unprocessed texture and brief natural decay. Only the described action. No speech, music, cartoon effects, cinematic bass, electronic tones or added background machinery.', '$.duration', CASE WHEN json_extract(config, '$.duration') = 2 THEN 2.5 ELSE json_extract(config, '$.duration') END) WHERE game = 'first-person' AND cue = 'material.mortar.grab' AND json_extract(config, '$.prompt') = 'Realistic close-miked construction Foley outdoors. Physically accurate weight and texture. One isolated action with a clean transient and short natural decay. No music, voices, cartoon boing, synthetic beep, distortion or exaggerated reverb. Scooping thick wet gritty mortar from a mixer into a bucket, viscous slop and metal rim scrape.';
UPDATE audio_cues SET config = json_set(config, '$.prompt', 'A steel bricklaying trowel deposits and draws a small bed of wet sandy mortar across rough brick: one thick sticky plop, close abrasive sand-grain rasp under the steel blade, then a short tacky peel as the trowel lifts. One compact laying stroke, not liquid pouring. Close natural location recording at arm length outdoors; believable weight, unprocessed texture and brief natural decay. Only the described action. No speech, music, cartoon effects, cinematic bass, electronic tones or added background machinery.', '$.duration', CASE WHEN json_extract(config, '$.duration') = 1 THEN 1.5 ELSE json_extract(config, '$.duration') END) WHERE game = 'first-person' AND cue = 'material.mortar.place' AND json_extract(config, '$.prompt') = 'Realistic close-miked construction Foley outdoors. Physically accurate weight and texture. One isolated action with a clean transient and short natural decay. No music, voices, cartoon boing, synthetic beep, distortion or exaggerated reverb. A steel trowel spreads wet grainy mortar on brick, short coarse metal scrape followed by a sticky wet squish.';
UPDATE audio_cues SET config = json_set(config, '$.prompt', 'One rough clay brick is pressed into a fresh mortar bed and nudged level: a soft dense contact followed by gritty wet compression, mortar squeezing at the edges and a tiny final clay adjustment tap. No dry hard landing or watery splash. Close natural location recording at arm length outdoors; believable weight, unprocessed texture and brief natural decay. Only the described action. No speech, music, cartoon effects, cinematic bass, electronic tones or added background machinery.', '$.duration', CASE WHEN json_extract(config, '$.duration') = 1 THEN 1.5 ELSE json_extract(config, '$.duration') END) WHERE game = 'first-person' AND cue = 'material.brick.wet' AND json_extract(config, '$.prompt') = 'Realistic close-miked construction Foley outdoors. Physically accurate weight and texture. One isolated action with a clean transient and short natural decay. No music, voices, cartoon boing, synthetic beep, distortion or exaggerated reverb. One clay brick pressed gently into a wet mortar bed, muted clay tap and short gritty wet compression.';
UPDATE audio_cues SET config = json_set(config, '$.prompt', 'A small electric mortar mixer starts at arm length outdoors: one mechanical switch click, a low motor hum rises in pitch as the drive engages, the steel drum gives two gear ticks and wet sand-and-cement paste begins folding against the internal paddles with slow heavy gritty slops. Natural small machine, no gravel rocks, diesel engine, speech or music.', '$.duration', CASE WHEN json_extract(config, '$.duration') = 2 THEN 2 ELSE json_extract(config, '$.duration') END) WHERE game = 'first-person' AND cue = 'mixer.start' AND json_extract(config, '$.prompt') = 'Realistic small electric cement mixer starting, mechanical switch click and electric motor spinning up into a rotating steel drum with wet gritty mortar. No voices or music.';
UPDATE audio_cues SET config = json_set(config, '$.prompt', 'A small electric steel-drum mortar mixer turns steadily at arm length outdoors. Constant low electric motor hum beneath regular dull gear ticks; dense wet sandy mortar lifts on the internal paddles and folds back in slow gritty sticky slops once per rotation. Stable speed and distance throughout, seamless repeating sound with no start or stop. No large stones, diesel engine, voices or music.', '$.duration', CASE WHEN json_extract(config, '$.duration') = 8 THEN 8 ELSE json_extract(config, '$.duration') END) WHERE game = 'first-person' AND cue = 'mixer.run' AND json_extract(config, '$.prompt') = 'Steady small electric cement mixer running, low electric motor hum, rotating steel drum and rhythmic gravelly wet mortar churning. Stable realistic close recording, seamless loop, no voices or music.';
UPDATE audio_cues SET config = json_set(config, '$.prompt', 'A small electric mortar mixer switches off: switch snaps, the motor hum falls in pitch and fades, spaced gear ticks slow with the steel drum, and heavy wet sandy paste slides down inside with a final sticky slop. Natural deceleration, no alarm beep, voice or music.', '$.duration', CASE WHEN json_extract(config, '$.duration') = 2 THEN 2 ELSE json_extract(config, '$.duration') END) WHERE game = 'first-person' AND cue = 'mixer.stop' AND json_extract(config, '$.prompt') = 'A small electric cement mixer motor switches off and its heavy steel drum slows to a stop with wet mortar settling, natural mechanical sound, no beep, voice or music.';
UPDATE audio_cues SET config = json_set(config, '$.prompt', 'A rotating small electric mortar mixer abruptly jams: one dull drive-gear clunk, a short low strained electrical hum while the drum stops, then the motor cuts out and the wet sandy load settles. Close modest machinery sound, no explosion, grinding destruction, alarm, speech or music.', '$.duration', CASE WHEN json_extract(config, '$.duration') = 2 THEN 2 ELSE json_extract(config, '$.duration') END) WHERE game = 'first-person' AND cue = 'mixer.jam' AND json_extract(config, '$.prompt') = 'Small electric cement mixer stalls with one restrained metallic clunk and a brief strained motor buzz that stops. Realistic machinery, no explosions, voices or music.';
UPDATE audio_cues SET config = json_set(config, '$.prompt', 'A work-gloved palm firmly nudges the steel frame of a stalled mortar mixer: soft glove contact over one hollow frame knock, a small gear clack as the drum frees, then a brief motor pickup with wet paste moving inside. One nudge, no hammer blows, voices or music.', '$.duration', CASE WHEN json_extract(config, '$.duration') = 2 THEN 2 ELSE json_extract(config, '$.duration') END) WHERE game = 'first-person' AND cue = 'mixer.fix' AND json_extract(config, '$.prompt') = 'A work-gloved hand bumps a steel cement mixer frame, short hollow metal knock, a gear releases and the motor resumes briefly, realistic, no music or voices.';
UPDATE audio_cues SET config = json_set(config, '$.prompt', 'A stationary steel mortar mixer drum is tipped to empty its remaining thick wet sand-and-cement paste: a short pivot creak and metal lip scrape, then several heavy cohesive gritty slops sliding over the rim, ending with a sticky strand breaking free. Dense paste, not a stream of water or loose gravel. No running motor, speech or music.', '$.duration', CASE WHEN json_extract(config, '$.duration') = 3 THEN 3 ELSE json_extract(config, '$.duration') END) WHERE game = 'first-person' AND cue = 'mixer.empty' AND json_extract(config, '$.prompt') = 'Thick wet sandy mortar sliding out of a steel cement mixer drum, heavy granular slop and short hollow metal scrape, realistic, no music or voices.';
